def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    opp_pressures = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            pressure = 0.0
            if opp.get('hp', 10) <= 3:
                pressure += 1.0
            if opp.get('no_water_days', 0) >= 1:
                pressure += 1.0
            if opp.get('budget', 0) > budget:
                pressure += 0.5
            opp_pressures.append(pressure)

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_pressure = max(opp_pressures) if opp_pressures else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    if no_water >= 2:
        danger += 1.0
    elif no_water >= 1:
        danger += 0.45

    base = 16.0 + 18.0 * scarcity + 10.0 * danger

    if highest_prev >= 120:
        if danger < 0.8 and supply >= 20:
            bid = 8.0 + 6.0 * scarcity
        else:
            bid = 78.0 + 10.0 * danger + 6.0 * scarcity
    elif highest_prev >= 90:
        if danger < 0.5 and supply >= 21:
            bid = 12.0 + 6.0 * scarcity
        else:
            bid = max(base + 10.0, min(highest_prev - 6.0, 82.0 + 8.0 * danger))
    elif highest_prev >= 60:
        bid = max(base + 8.0, highest_prev + 2.0)
    elif highest_prev > 0:
        bid = max(base, avg_prev + 4.0)
    else:
        bid = base

    if max_pressure >= 1.5 and danger >= 0.5:
        bid += 8.0

    if supply >= 23 and danger < 0.5:
        bid *= 0.72
    elif supply >= 20 and danger < 0.5:
        bid *= 0.85
    elif supply <= 16:
        bid += 10.0

    if day >= 8:
        bid += 6.0 * danger + 3.0 * scarcity

    safe_cap = budget
    if budget > DAILY_SALARY * 8:
        safe_cap = min(budget, 110.0)
    elif budget > DAILY_SALARY * 5:
        safe_cap = min(budget, 95.0)
    else:
        safe_cap = min(budget, 82.0 + 10.0 * danger)

    if danger >= 1.5:
        bid = max(bid, 88.0)
        safe_cap = budget
    elif danger >= 1.0:
        bid = max(bid, 72.0)

    if hp >= 7 and no_water == 0 and supply >= 22 and highest_prev >= 90:
        bid = min(bid, 15.0)

    bid = max(0.0, min(float(bid), float(safe_cap)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, bid conservatively
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday trace bids for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely available relative to my requirement
    # (use only to tune aggressiveness, not to index arrays)
    supply_ratio = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0

    # Base bid target: aim to beat typical mid/high bids without exhausting budget
    # Observed: Cindy ~92.5, Eric ~73.6; use 0.75-0.95 of DAILY_SALARY depending on conditions.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        # Critical survival pressure: bid near top of our comfort range
        target = DAILY_SALARY * 0.95
    elif supply_ratio >= 2.0:
        # Plenty of supply: don't overspend
        target = DAILY_SALARY * 0.65
    else:
        # Moderate supply: try to secure enough water against high bidders
        target = DAILY_SALARY * 0.78

    # If yesterday saw very high bids, slightly increase to avoid being outbid
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        target = max(target, DAILY_SALARY * 0.9)
    elif highest_prev_bid >= DAILY_SALARY * 0.75:
        target = max(target, DAILY_SALARY * 0.82)

    # Ensure bid respects budget and keeps some buffer
    # If budget is low, scale down proportionally.
    if my_budget <= 0:
        return 0.0

    # Keep at least a small fraction for future days
    budget_cap = my_budget * 0.95
    bid = min(budget_cap, target)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

